CREATE TYPE "ExamType" AS ENUM ('QUIZ', 'MIDTERM', 'FINAL', 'PRACTICAL', 'OTHER');
CREATE TABLE "Exam" ("id" UUID NOT NULL, "schoolId" UUID NOT NULL, "semesterId" UUID NOT NULL, "name" TEXT NOT NULL, "type" "ExamType" NOT NULL, "startsOn" DATE NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), CONSTRAINT "Exam_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExamSubject" ("id" UUID NOT NULL, "examId" UUID NOT NULL, "teachingAssignmentId" UUID NOT NULL, "maximumScore" DOUBLE PRECISION NOT NULL, "scheduledAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ExamSubject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Mark" ("id" UUID NOT NULL, "examSubjectId" UUID NOT NULL, "studentId" UUID NOT NULL, "score" DOUBLE PRECISION NOT NULL, "remarks" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Mark_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GradingScale" ("id" UUID NOT NULL, "schoolId" UUID NOT NULL, "letter" TEXT NOT NULL, "minimum" DOUBLE PRECISION NOT NULL, "maximum" DOUBLE PRECISION NOT NULL, "gradePoint" DOUBLE PRECISION NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GradingScale_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Exam_schoolId_semesterId_idx" ON "Exam"("schoolId", "semesterId"); CREATE UNIQUE INDEX "ExamSubject_examId_teachingAssignmentId_key" ON "ExamSubject"("examId", "teachingAssignmentId"); CREATE UNIQUE INDEX "Mark_examSubjectId_studentId_key" ON "Mark"("examSubjectId", "studentId"); CREATE INDEX "Mark_studentId_idx" ON "Mark"("studentId"); CREATE UNIQUE INDEX "GradingScale_schoolId_letter_key" ON "GradingScale"("schoolId", "letter"); CREATE INDEX "GradingScale_schoolId_minimum_idx" ON "GradingScale"("schoolId", "minimum");
ALTER TABLE "Exam" ADD CONSTRAINT "Exam_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Exam" ADD CONSTRAINT "Exam_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "Semester"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ExamSubject" ADD CONSTRAINT "ExamSubject_examId_fkey" FOREIGN KEY ("examId") REFERENCES "Exam"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ExamSubject" ADD CONSTRAINT "ExamSubject_teachingAssignmentId_fkey" FOREIGN KEY ("teachingAssignmentId") REFERENCES "TeachingAssignment"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Mark" ADD CONSTRAINT "Mark_examSubjectId_fkey" FOREIGN KEY ("examSubjectId") REFERENCES "ExamSubject"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Mark" ADD CONSTRAINT "Mark_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "GradingScale" ADD CONSTRAINT "GradingScale_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
